// Photos (hero, course thumbnails, avatars), generated by `npm run images`
// (scripts/images.mjs) as AVIF and WebP at several widths:
//   src/assets/photos/<id>-<width>.<avif|webp>
// Vite hashes each file; this module maps them to srcsets.

const files = import.meta.glob('../assets/photos/*.{avif,webp}', { eager: true, query: '?url', import: 'default' });

const index = {};
for (const [path, url] of Object.entries(files)) {
  const m = /\/([a-z0-9-]+)-(\d+)\.(avif|webp)$/.exec(path);
  if (!m) continue;
  const [, id, width, format] = m;
  index[id] ??= { avif: [], webp: [] };
  index[id][format].push([Number(width), url]);
}
for (const entry of Object.values(index)) {
  entry.avif.sort((a, b) => a[0] - b[0]);
  entry.webp.sort((a, b) => a[0] - b[0]);
}

const RATIO = { hero: 5 / 4, course: 9 / 16, avatar: 1 };
const srcset = (list, max = Infinity) =>
  list
    .filter(([w]) => w <= max)
    .map(([w, url]) => `${url} ${w}w`)
    .join(', ');

/** { avif, webp, src, width, height } for a photo id, or null if it's missing. */
export function imageFor(id, { max = Infinity, kind = 'course' } = {}) {
  const entry = index[id];
  if (!entry || !entry.webp.length) return null;
  const fallback = entry.webp.filter(([w]) => w <= max).at(-1) ?? entry.webp[0];
  const largest = entry.webp.at(-1)[0];
  return { avif: srcset(entry.avif, max), webp: srcset(entry.webp, max), src: fallback[1], width: largest, height: Math.round(largest * RATIO[kind]) };
}

export const imageUrl = (id, width, format = 'webp') => index[id]?.[format].find(([w]) => w === width)?.[1] ?? null;
export const hasImage = (id) => Boolean(index[id]);

/** The home hero's `sizes` (the <img> and the preload in the head must agree). */
export const HERO_SIZES = '(min-width: 1184px) 480px, (min-width: 1024px) 40vw, (min-width: 768px) 520px, calc(100vw - 32px)';
export const heroImage = () => imageFor('hero', { kind: 'hero' });
